import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { LockfileError, findDependencyPaths, parsePnpmLockfile } from '../src/index.js';

// Generated by pnpm 10: a workspace with peer dependencies, an npm alias and an optional dependency.
const fixture = readFileSync(new URL('./fixtures/pnpm-workspace.yaml', import.meta.url), 'utf8');

describe('parsePnpmLockfile', () => {
  const graph = parsePnpmLockfile(fixture, { name: 'pnpm-sample', version: '1.2.3' });
  const pkg = (id: string) => graph.packages.get(id);

  it('uses the root passed in', () => {
    expect(graph.root).toEqual({ name: 'pnpm-sample', version: '1.2.3' });
  });

  it('lists direct dependencies for every importer', () => {
    expect(graph.directDependencies).toEqual([
      { id: 'lib@link:packages/lib', type: 'prod', importer: '.' },
      { id: 'react@18.2.0', type: 'prod', importer: '.' },
      { id: 'react-dom@18.2.0', type: 'prod', importer: '.' },
      { id: 'string-width@4.2.3', type: 'prod', importer: '.' },
      { id: 'debug@4.3.4', type: 'dev', importer: '.' },
      { id: 'fsevents@2.3.3', type: 'optional', importer: '.' },
      { id: 'ms@2.1.3', type: 'prod', importer: 'packages/lib' },
    ]);
  });

  it('strips peer suffixes from versions', () => {
    expect(pkg('react-dom@18.2.0')?.dependencies).toEqual([
      'loose-envify@1.4.0',
      'react@18.2.0',
      'scheduler@0.23.2',
    ]);
  });

  it('resolves npm aliases to the real package', () => {
    expect(pkg('string-width@4.2.3')?.dependencies).toContain('strip-ansi@6.0.1');
    expect(graph.packages.has('sw@4.2.3')).toBe(false);
  });

  it('links workspace packages to their own dependencies', () => {
    expect(pkg('lib@link:packages/lib')).toMatchObject({ local: true, dependencies: ['ms@2.1.3'] });
  });

  it('marks packages only reachable through devDependencies as dev', () => {
    expect(pkg('debug@4.3.4')?.dev).toBe(true);
    expect(pkg('ms@2.1.2')?.dev).toBe(true);
    expect(pkg('ms@2.1.3')?.dev).toBe(false);
    expect(pkg('loose-envify@1.4.0')?.dev).toBe(false);
  });

  it('carries optional flags', () => {
    expect(pkg('fsevents@2.3.3')?.optional).toBe(true);
    expect(pkg('react@18.2.0')?.optional).toBe(false);
  });

  it('explains transitive packages', () => {
    expect(findDependencyPaths(graph, 'ms@2.1.3')).toEqual([
      ['ms@2.1.3'],
      ['lib@link:packages/lib', 'ms@2.1.3'],
    ]);
  });

  it('merges snapshots of the same version with different peers', () => {
    const merged = parsePnpmLockfile(`
lockfileVersion: '9.0'
importers:
  .:
    dependencies:
      a: { specifier: '1', version: 1.0.0 }
      b: { specifier: '1', version: 1.0.0 }
snapshots:
  a@1.0.0:
    dependencies:
      plugin: 1.0.0(peer@1.0.0)
  b@1.0.0:
    dependencies:
      plugin: 1.0.0(peer@2.0.0)
  plugin@1.0.0(peer@1.0.0):
    dependencies:
      peer: 1.0.0
  plugin@1.0.0(peer@2.0.0):
    dependencies:
      peer: 2.0.0
  peer@1.0.0: {}
  peer@2.0.0: {}
`);
    expect(merged.packages.get('plugin@1.0.0')?.dependencies).toEqual(['peer@1.0.0', 'peer@2.0.0']);
  });

  it('rejects older lockfile versions', () => {
    expect(() => parsePnpmLockfile("lockfileVersion: '6.0'\n")).toThrow(LockfileError);
  });

  it('rejects invalid YAML', () => {
    expect(() => parsePnpmLockfile('a: [')).toThrow(LockfileError);
  });
});
